registerModuleVariants("dinner.waiter.italian", [{ when: {}, text: ["A round, bustling server beams and refills the bread without ceremony.", "\"More? Of course more.\" Family Italian logic, delivered with warmth."] }]);
registerModuleVariants("dinner.waiter.steakhouse._f1", [{ when: {}, text: ["\"I know,\" she answers, warm and unhurried.", "\"I could get used to this,\" she says, almost to herself."] }]);
registerModuleVariants("dinner.waiter.steakhouse._f2", [{ when: {}, text: [". Comfort arrives in layers — food, heat, permission.", ". Her voice goes soft around the edges of want."] }]);
registerModuleVariants("dinner.waiter.steakhouse", [{ when: {}, text: ["A solid woman in a leather apron surveys cleared plates with approval.", "She nods at the wreckage of courses. \"Next round?\" Professional, unhurried."] }]);
registerModuleVariants("dinner.waiter.french._f1", [{ when: {}, text: ["\"That looks incredible,\" she admits, already reaching.", "\"Don't stop,\" she murmurs — meaning the food, maybe more."] }]);
registerModuleVariants("dinner.waiter.french", [{ when: {}, text: ["The sommelier drifts over — substantial, crisp, refilling wine without comment.", "Formal service, soft authority: \"Another course?\""] }]);
registerModuleVariants("dinner.waiter.japanese._f1", [{ when: {}, text: ["She appears and vanishes like ritual; {subject.name} reaches for the fresh menu.", "Quiet formal service — chopsticks replaced, water refreshed, menu waiting."] }]);
registerModuleVariants("dinner.waiter.japanese", [{ when: {}, text: ["She appears and vanishes like ritual; {subject.name} reaches for the fresh menu.", "Quiet formal service — chopsticks replaced, water refreshed, menu waiting."] }]);
registerModuleVariants("dinner.waiter.private_club._f1", [{ when: {}, text: ["Discreet service in a private room — anticipation handled like luxury.", "The server knows when to appear; the next course is already implied."] }]);
