registerModuleVariants("dinner.waiter.chefs_table._f1", [{ when: {}, text: ["The kitchen sends its ambassador — pride and portions in equal measure.", "Chef's-table service: each arrival feels like an event."] }]);
registerModuleVariants("dinner.waiter.chefs_table._f2", [{ when: {}, text: ["\"I could get used to this,\" she says, almost to herself.", "\"I know,\" she answers, warm and unhurried."] }]);
registerModuleVariants("dinner.waiter.chefs_table", [{ when: {}, text: ["The kitchen sends its ambassador — pride and portions in equal measure.", "Chef's-table service: each arrival feels like an event."] }]);
registerModuleVariants("dinner.waiter.home_dinner._f1", [{ when: {}, text: ["You clear space and bring more — domestic warmth, no performance.", "The table is yours; seconds land like love language."] }]);
registerModuleVariants("dinner.waiter.home_dinner", [{ when: {}, text: ["You clear space and bring more — domestic warmth, no performance.", "The table is yours; seconds land like love language."] }]);
registerModuleVariants("dinner.waiter.brunch_hall._f1", [{ when: {}, text: ["\"That looks incredible,\" she admits, already reaching.", "\"Don't stop,\" she murmurs — meaning the food, maybe more."] }]);
registerModuleVariants("dinner.waiter.brunch_hall", [{ when: {}, text: ["Brunch service hums — syrup, coffee, and another plate before she asks.", "The hall runs on abundance; your server keeps pace without fuss."] }]);
registerModuleVariants("dinner.waiter.atelier._f1", [{ when: {}, text: ["\"Don't stop,\" she murmurs — meaning the food, maybe more.", "\"That looks incredible,\" she admits, already reaching."] }]);
registerModuleVariants("dinner.waiter.atelier._f2", [{ when: {}, text: ["Each course arrives like a small ceremony; appetite is part of the design.", "Artful service matches artful plates — precision with indulgence underneath."] }]);
registerModuleVariants("dinner.waiter.atelier", [{ when: {}, text: ["Artful service matches artful plates — precision with indulgence underneath.", "Each course arrives like a small ceremony; appetite is part of the design."] }]);
registerModuleVariants("dinner.waiter", [{ when: {}, text: ["Soft laughter and clinking glass; the evening leans toward indulgence.", "Candlelight catches the curve of her satisfaction — unhurried, present, real."] }]);
registerModuleVariants("dinner.setup", [{ when: {}, text: ["Comfort pools in her middle; she makes no move to hide it.", "Warmth and fullness settle between you — patient, sensual, sure."] }]);
registerModuleVariants("dinner.courseReaction", [{ when: {}, text: ["Candlelight catches the curve of her satisfaction — unhurried, present, real.", "Soft laughter and clinking glass; the evening leans toward indulgence."] }]);
registerModuleVariants("dinner.endReflection", [{ when: {}, text: ["She eats with the ease of someone finally allowed to want.", "The table holds warmth between courses; appetite has its own gravity tonight."] }]);
registerModuleVariants("dinner.exit", [{ when: {}, text: ["She eats with the ease of someone finally allowed to want.", "The table holds warmth between courses; appetite has its own gravity tonight."] }]);
