registerModuleVariants("dinner.endOpen", [{ when: {}, text: ["{subject.name} leans back as the last plate clears — warm, full, unhurried.", "The meal winds down; {subject.name} looks satisfied in the deep way only a long dinner produces."] }]);
registerModuleVariants("dinner.endClose", [{ when: {}, text: ["She pats her middle once, content. \"That was exactly what I needed.\"", "The check arrives; she is in no hurry to leave — fullness has its own gravity."] }]);
registerModuleVariants("dinner.ending", [{ when: {}, text: ["{dinner.endOpen}\n{dinner.endClose}", "{dinner.endOpen} {dinner.endClose}"] }]);
